let chatId = 'ĐIỀN_CHAT_ID_CỦA_BẠN_VÀO_ĐÂY';
let isAuto = true;
let text = '';
try {
  const msg = $('Execute Workflow Trigger').item.json.message;
  if (msg && msg.chat && msg.chat.id) {
    chatId = msg.chat.id;
    text = msg.text.toLowerCase();
    isAuto = false;
  }
} catch(e) {}

let topics = [];
if (isAuto) {
  topics = ['kinh-doanh', 'the-gioi', 'so-hoa'];
} else {
  if (text.includes('kinhdoanh') || text.includes('business')) topics.push('kinh-doanh');
  if (text.includes('thegioi') || text.includes('world')) topics.push('the-gioi');
  if (text.includes('congnghe') || text.includes('tech') || text.includes('sohoa')) topics.push('so-hoa');
  if (text.includes('thoisu') || text.includes('news')) topics.push('thoi-su');
  if (text.includes('suckhoe') || text.includes('health')) topics.push('suc-khoe');
  if (text.includes('thethao') || text.includes('sport')) topics.push('the-thao');
  if (text.includes('giaitri') || text.includes('entertainment')) topics.push('giai-tri');
  if (text.includes('phapluat') || text.includes('law')) topics.push('phap-luat');
  if (text.includes('giaoduc') || text.includes('education')) topics.push('giao-duc');
  if (text.includes('doisong') || text.includes('life')) topics.push('doi-song');
  if (text.includes('xe') || text.includes('car')) topics.push('xe');
  if (text.includes('dulich') || text.includes('travel')) topics.push('du-lich');
  if (text.includes('khoahoc') || text.includes('science')) topics.push('khoa-hoc');

  if (topics.length === 0) topics = ['kinh-doanh', 'the-gioi', 'so-hoa'];
}

const topicNames = {
  'kinh-doanh': 'Kinh doanh', 'the-gioi': 'Thế giới', 'so-hoa': 'Công nghệ',
  'thoi-su': 'Thời sự', 'suc-khoe': 'Sức khỏe', 'the-thao': 'Thể thao',
  'giai-tri': 'Giải trí', 'phap-luat': 'Pháp luật', 'giao-duc': 'Giáo dục',
  'doi-song': 'Đời sống', 'xe': 'Xe', 'du-lich': 'Du lịch', 'khoa-hoc': 'Khoa học'
};

return topics.map(t => ({
  json: {
    url: `https://vnexpress.net/rss/${t}.rss`,
    topic: topicNames[t] || 'Tin tức',
    chatId: chatId,
    isAuto: isAuto
  }
}));

const staticData = $getWorkflowStaticData('global');
staticData.sentUrls = staticData.sentUrls || [];
let allItems = [];
let chatId = '';
let isAuto = false;

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

for (const [index, item] of $input.all().entries()) {
  chatId = $('Chuẩn bị URL News').all()[index].json.chatId;
  isAuto = $('Chuẩn bị URL News').all()[index].json.isAuto;
  const topic = $('Chuẩn bị URL News').all()[index].json.topic || 'Tin tức';
  let articles = item.json.rss?.channel?.item || [];
  if (!Array.isArray(articles)) articles = [articles];

  for (const article of articles) {
    if (!article.title || !article.link) continue;
    let pubDate = 0;
    try { pubDate = new Date(article.pubDate).getTime(); } catch (e) {}
    allItems.push({
      title: article.title,
      link: article.link,
      pubDate,
      topic
    });
  }
}

allItems.sort((a, b) => b.pubDate - a.pubDate);
let finalItems = [];
for (const article of allItems) {
  if (isAuto && staticData.sentUrls.includes(article.link)) continue;
  finalItems.push(article);
  if (finalItems.length >= 8) break;
}

if (isAuto) {
  for (const article of finalItems) staticData.sentUrls.push(article.link);
  if (staticData.sentUrls.length > 200) staticData.sentUrls = staticData.sentUrls.slice(-200);
}

if (finalItems.length === 0) {
  return [{ json: { text: '📰 <b>Tin tức mới</b>\n\nHiện chưa có bài mới để gửi.', chatId } }];
}

const uniqueTopics = [...new Set(finalItems.map(item => item.topic))];
const topicLine = uniqueTopics.slice(0, 3).join(' • ');
let message = '📰 <b>Tin tức nổi bật</b>\n';
message += `<i>${escapeHtml(topicLine)}</i>\n\n`;

for (let i = 0; i < finalItems.length; i++) {
  const item = finalItems[i];
  message += `<b>${i + 1}. ${escapeHtml(item.topic)}</b>\n`;
  message += `• <a href="${escapeHtml(item.link)}">${escapeHtml(item.title)}</a>\n\n`;
}

message = message.trim();
return [{ json: { text: message, chatId } }];
